public class Cagepa {
public static void main(String[] args) {
Cagepa ip = new Cagepa();
System.out.println("Resultado=" +
ip.Cagepa(5));
}
private int Cagepa(int x) {
if(x == 0)
return 0;
if(x % 2 != 0)
return x + Cagepa(x - 1)+4;
return Cagepa(x - 1);
}
}
